import { BEES_ALERT_ILLUSTRATION } from '../../Image/Image.constants';
import type {
  EmptyStateCustomImage,
  EmptyStateIllustrationName,
} from '../EmptyState.types';

const illustrationMap: Record<
  EmptyStateIllustrationName,
  { src: string; alt: string }
> = {
  beesAlert: BEES_ALERT_ILLUSTRATION,
};

export const getIllustration = (
  customIlustration?: EmptyStateCustomImage,
  ilustrationName: EmptyStateIllustrationName = 'beesAlert',
): EmptyStateCustomImage => {
  if (customIlustration) {
    return customIlustration;
  }

  const illustration =
    illustrationMap[ilustrationName] ?? BEES_ALERT_ILLUSTRATION;

  return {
    alt: illustration.alt,
    src: illustration.src,
  };
};
